class GenerateTtiTrace(RtgGenerateTtiTrace):
    """Command for execute generate tti trace script."""

    def __init__(self, connection, src, dst, path="/opt/cus/lib/wireshark_adapter_to_ttitrace/generate_tti_trace.py",
                 options=None, prompt=None, newline_chars=None, runner=None):
        """
        Generate tti trace command.

        :param connection: moler connection to device, terminal when command is executed.
        :param options: parameter with which the command will be executed
        :param src: Path to directory with pcaps.
        :param dst: Path to target directory for tti trace.
        :param path: Path to generate_tti_trace.py file.
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(GenerateTtiTrace, self).__init__(connection, src, dst, path=path, options=options, prompt=prompt,
                                               newline_chars=newline_chars, runner=runner)


